mapper.update:
UPDATE acceleration_daily_charge
SET paid_delinquency_charge = paid_delinquency_charge + #{amount}
WHERE acceleration_daily_charge_id = #{accelerationDailyChargeId}

UPDATE acceleration_daily_charge
SET paid_interest = paid_interest + #{amount}
WHERE acceleration_daily_charge_id = #{accelerationDailyChargeId}



UPDATE acceleration_daily_charge adc
JOIN loan_acceleration a ON a.loan_acceleration_id = adc.loan_acceleration_id
SET adc.delinquency_status_id = #{resolved}
WHERE a.loan_account_id = #{loanAccountId}
  AND adc.delinquency_status_id = #{inProgress}
  AND adc.paid_delinquency_charge >= adc.delinquency_charge
  AND adc.paid_interest >= adc.interest_amount
